<input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?=$n['id']?>"><button class="smallbtn">Mark read</button></form><?php endif;?></div><?php endforeach;endif;?></main></body></html>